using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;

static class ThemedNotice {
 public static void Show(IWin32Window owner,string title,string message){using(var form=new Form()){form.Text="Maquetario";form.FormBorderStyle=FormBorderStyle.None;form.StartPosition=owner==null?FormStartPosition.CenterScreen:FormStartPosition.CenterParent;form.ClientSize=new Size(570,310);form.BackColor=Color.FromArgb(20,41,47);form.ForeColor=Color.FromArgb(244,245,238);form.Font=new Font("Segoe UI",10);form.Padding=new Padding(24);form.ShowInTaskbar=false;form.Paint+=delegate(object sender,PaintEventArgs e){using(var gradient=new LinearGradientBrush(form.ClientRectangle,Color.FromArgb(35,66,70),Color.FromArgb(15,30,39),45f))e.Graphics.FillRectangle(gradient,form.ClientRectangle);using(var pen=new Pen(Color.FromArgb(112,180,165)))e.Graphics.DrawRectangle(pen,0,0,form.Width-1,form.Height-1);};var eyebrow=new Label{Text="MAQUETARIO · AVISO",AutoSize=true,Location=new Point(25,20),ForeColor=Color.FromArgb(228,177,108),BackColor=Color.Transparent,Font=new Font("Segoe UI",9,FontStyle.Bold)};var heading=new Label{Text=title,AutoSize=false,Location=new Point(25,53),Size=new Size(520,55),BackColor=Color.Transparent,Font=new Font("Segoe UI",16,FontStyle.Bold)};var body=new Label{Text=message,AutoSize=false,Location=new Point(25,113),Size=new Size(520,122),BackColor=Color.Transparent};var button=new Button{Text="Cerrar / Close",DialogResult=DialogResult.OK,Location=new Point(389,252),Size=new Size(156,37),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(60,209,187),ForeColor=Color.FromArgb(16,52,48)};button.FlatAppearance.BorderColor=Color.FromArgb(121,226,203);form.Controls.Add(eyebrow);form.Controls.Add(heading);form.Controls.Add(body);form.Controls.Add(button);form.AcceptButton=form.CancelButton=button;if(owner==null)form.ShowDialog();else form.ShowDialog(owner);}}
}
